package dev.zomboid.gore;
import java.util.*;
/** Synced momentum with hit direction and strength, without prolonging the AI stun. */
public final class MeleeReaction{
 static final Map<Object,Reaction>REACTIONS=new WeakHashMap<>();static final Map<Object,List<Offset>>OFFSETS=new WeakHashMap<>();
 record Reaction(int tick,int direction,int kind){}record Offset(Object part,float x,float y,float z){}
 public static boolean event(Object v,byte code){if(code> -101||code< -112||!Gore.zombie(v))return false;int n=-101-code;REACTIONS.put(v,new Reaction(((Number)R.get(v,"tickCount")).intValue(),n%3,n/3));return true;}
 public static float envelope(float t){if(t<=0||t>=15)return 0;double attack=Math.min(1,t/1.6),decay=Math.max(0,1-(t-1.6)/13.4);return(float)(attack*attack*(3-2*attack)*decay*decay);}
 static void adjust(Object p,String n,float d){R.set(p,n,((Number)R.get(p,n)).floatValue()+d);}
 public static void reset(Object model){List<Offset> old=OFFSETS.remove(model);if(old!=null)for(Offset a:old){adjust(a.part,"xRot",-a.x);adjust(a.part,"yRot",-a.y);adjust(a.part,"zRot",-a.z);}}
 static void add(Object model,List<Offset>out,String name,float x,float y,float z){Object p=R.get(model,name);if(p==null)return;adjust(p,"xRot",x);adjust(p,"yRot",y);adjust(p,"zRot",z);out.add(new Offset(p,x,y,z));}
 public static void pose(Object model,Object v,float age){Reaction r=REACTIONS.get(v);if(r==null||!Gore.zombie(v))return;float t=age-r.tick;if(t>=15){REACTIONS.remove(v);return;}float a=envelope(t)*(r.kind==0?.6f:r.kind==1?1.15f:r.kind==2?.95f:1.3f),head=envelope(t-.7f),side=r.direction==0?-1:r.direction==1?1:0;List<Offset>out=new ArrayList<>(6);add(model,out,"body",-.25f*a,.16f*a*side,.15f*a*side);add(model,out,"head",-.30f*a*head,.23f*a*side,.12f*a*side);add(model,out,"rightArm",-.30f*a,-.10f*a,.28f*a);add(model,out,"leftArm",-.24f*a,.10f*a,-.20f*a);add(model,out,"rightLeg",.14f*a,0,.07f*a*side);add(model,out,"leftLeg",-.08f*a,0,.04f*a*side);OFFSETS.put(model,out);}
 public static void damage(Object e){Object v=R.call(e,"getEntity");if(!Gore.zombie(v)||Gore.shots.get()!=null||R.num(R.call(e,"getNewDamage"))<=0||R.yes(R.get(R.call(v,"level"),"isClientSide")))return;Object source=R.call(e,"getSource"),p=R.call(source,"getEntity");if(p==null||p!=R.call(source,"getDirectEntity")||!Set.of("player","mob","mob_attack","mob_attack_no_aggro").contains(R.call(source,"getMsgId")))return;double yaw=Math.toRadians(R.num(R.call(v,"getYRot"))),dx=R.num(R.call(p,"getX"))-R.num(R.call(v,"getX")),dz=R.num(R.call(p,"getZ"))-R.num(R.call(v,"getZ")),side=dx*Math.cos(yaw)+dz*Math.sin(yaw);int direction=Math.abs(side)<.25?2:side<0?0:1,kind=R.num(R.call(e,"getNewDamage"))>=3?1:0;try{Object action=((ThreadLocal<?>)R.get(R.type("dev.zomboidmelee.boxing.Combat18"),"ACTION")).get();if(Integer.valueOf(1).equals(action))kind=1;if(Integer.valueOf(2).equals(action))kind=3;}catch(IllegalStateException absent){}Object tag=R.call(p,"getPersistentData");if(R.yes(R.call(tag,"getBoolean","zpush_active")))kind=2;if(R.num(R.call(e,"getNewDamage"))>=10)kind=3;R.call(R.call(v,"level"),"broadcastEntityEvent",v,(byte)(-101-direction-kind*3));}
}
